1	import assert from 'node:assert/strict';
2	import { test } from 'node:test';
3	import { app } from '../src/server.mjs';
4	import { counters } from '../src/metrics.mjs';
5	
6	/**
7	 * Вспомогательная функция для HTTP-запросов к app().
8	 * Симулирует HTTP-запрос без поднятия реального сервера.
9	 * 
10	 * @param {string} url - путь запроса (например, '/quote')
11	 * @param {string} method - HTTP метод (GET, POST, etc.)
12	 * @param {object|string|null} body - тело запроса
13	 * @param {object} customHeaders - дополнительные заголовки запроса (переопределяют дефолтные)
14	 */
15	async function request(url, method = 'GET', body = null, customHeaders = {}) {
16	  const defaultHeaders = body ? { 'content-type': 'application/json' } : {};
17	  const req = {
18	    url,
19	    method,
20	    headers: { ...defaultHeaders, ...customHeaders },
21	  };
22	
23	  const chunks = [];
24	  const res = {
25	    statusCode: null,
26	    headers: {},
27	    writeHead: function(code, headers) {
28	      this.statusCode = code;
29	      this.headers = headers;
30	    },
31	    write: function(chunk) {
32	      if (typeof chunk === 'string') {
33	        chunks.push(Buffer.from(chunk));
34	      } else {
35	        chunks.push(chunk);
36	      }
37	    },
38	    end: function(chunk) {
39	      if (chunk) {
40	        if (typeof chunk === 'string') {
41	          chunks.push(Buffer.from(chunk));
42	        } else {
43	          chunks.push(chunk);
44	        }
45	      }
46	    },
47	  };
48	
49	  // Если есть тело, имитируем readable stream
50	  if (body) {
51	    let bodyStr;
52	    if (typeof body === 'string') {
53	      bodyStr = body;
54	    } else {
55	      bodyStr = JSON.stringify(body);
56	    }
57	    req[Symbol.asyncIterator] = async function*() {
58	      yield Buffer.from(bodyStr);
59	    };
60	  } else {
61	    req[Symbol.asyncIterator] = async function*() {
62	      // Пустой body
63	    };
64	  }
65	
66	  await app(req, res);
67	
68	  const responseBody = Buffer.concat(chunks).toString('utf8');
69	  let parsedBody;
70	  try {
71	    parsedBody = JSON.parse(responseBody);
72	  } catch {
73	    parsedBody = responseBody;
74	  }
75	
76	  return {
77	    statusCode: res.statusCode,
78	    headers: res.headers,
79	    body: parsedBody,
80	  };
81	}
82	
83	test('GET /stats возвращает начальные нули', async () => {
84	  const res = await request('/stats', 'GET');
85	  assert.equal(res.statusCode, 200);
86	  assert.deepEqual(res.body, { visits: 0, successes: 0 });
87	});
88	
89	test('POST /quote инкрементирует visits', async () => {
90	  const before = counters.getStats().visits;
91	  await request('/quote', 'POST', {
92	    items: [{ sku: 'a', price: 1000, qty: 1 }],
93	  });
94	  const after = counters.getStats().visits;
95	  assert.equal(after, before + 1);
96	});
97	
98	test('POST /quote инкрементирует successes при успешном запросе', async () => {
99	  const before = counters.getStats().successes;
100	  await request('/quote', 'POST', {
101	    items: [{ sku: 'a', price: 1000, qty: 1 }],
102	  });
103	  const after = counters.getStats().successes;
104	  assert.equal(after, before + 1);
105	});
106	
107	test('GET /healthz не инкрементирует visits', async () => {
108	  const before = counters.getStats().visits;
109	  await request('/healthz', 'GET');
110	  const after = counters.getStats().visits;
111	  assert.equal(after, before);
112	});
113	
114	test('POST /quote с невалидным JSON инкрементирует visits, но не successes', async () => {
115	  const beforeVisits = counters.getStats().visits;
116	  const beforeSuccesses = counters.getStats().successes;
117	  
118	  await request('/quote', 'POST', '{invalid json}');
119	  
120	  const afterVisits = counters.getStats().visits;
121	  const afterSuccesses = counters.getStats().successes;
122	  
123	  assert.equal(afterVisits, beforeVisits + 1);
124	  assert.equal(afterSuccesses, beforeSuccesses);
125	});
126	
127	test('POST /quote с пустым заказом инкрементирует visits, но не successes', async () => {
128	  const beforeVisits = counters.getStats().visits;
129	  const beforeSuccesses = counters.getStats().successes;
130	  
131	  await request('/quote', 'POST', { items: [] });
132	  
133	  const afterVisits = counters.getStats().visits;
134	  const afterSuccesses = counters.getStats().successes;
135	  
136	  assert.equal(afterVisits, beforeVisits + 1);
137	  assert.equal(afterSuccesses, beforeSuccesses);
138	});
139	
140	test('GET /stats после нескольких запросов возвращает корректные значения', async () => {
141	  const beforeVisits = counters.getStats().visits;
142	  const beforeSuccesses = counters.getStats().successes;
